/**
 * Open-source licenses — the third-party components bundled in this build
 * (`src/legal/licenses.json`, generated by `scripts/export-licenses.ts`).
 */
import type { ReactNode } from 'react';
import { View } from 'react-native';
import { useSafeAreaInsets } from 'react-native-safe-area-context';

import { OpenSourceLicensesList } from '@/components/legal/OpenSourceLicensesList';
import { SettingsScreenTitle } from '@/components/settings/SettingsBlocks';
import { useTranslation } from '@/i18n';
import { safeBack } from '@/navigation/safeBack';

export default function OpenSourceLicensesPage(): ReactNode {
  const insets = useSafeAreaInsets();
  const { t } = useTranslation();
  return (
    <View className="flex-1 bg-pageBg" style={{ paddingTop: insets.top }}>
      <SettingsScreenTitle
        title={t('licenses.title')}
        leadingAction={{ accessibilityLabel: t('common.back'), onPress: () => { safeBack(); } }}
      />
      <OpenSourceLicensesList />
    </View>
  );
}
